/**
 * Scaffold a minimal BDK project (`agent-sdk init`).
 */
import { spawn } from "node:child_process";
import { existsSync, lstatSync } from "node:fs";
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { basename, dirname, join, relative, resolve } from "node:path";
import { runfiles } from "@bazel/runfiles";
import { DEFAULT_MODEL } from "../types.js";
import { canonicalTemplateName, isTemplateName, readCursorAgentTemplate, } from "./cursor-agent-template.js";
import { CLI_COMMAND_NAME, FORMER_PACKAGE_NAME, PACKAGE_NAME, PREVIOUS_PACKAGE_NAME, packageRootDir, packageVersion, } from "./distribution.js";
import { applyInitReplacements, isTemplateMetaPath, loadTemplateInitSpec, posixRel, templateFileHasReplacements, } from "./init-interview.js";
import { agentsMd, formatModelLiteral, GITIGNORE, writeDefaultScaffold } from "./init-scaffold.js";
import { remapCanonicalProjectContents, remapCanonicalProjectPath, resolveProjectRoot, } from "./project-layout.js";
import { makePalette, stdoutPalette } from "./terminal-style.js";
const TEMPLATES = {
    "agentic-owners": { dir: "agentic-owners" },
    "agents-md": { dir: "agents-md" },
    "code-wiki": { dir: "code-wiki" },
    demo: { dir: "demo" },
    "pr-autofixer": { dir: "pr-autofixer" },
    "security-help": { dir: "security-help" },
    "security-reviewer": { dir: "security-reviewer" },
    "thermo-quality-review": { dir: "thermo-quality-review" },
    "thermo-review": { dir: "thermo-review" },
    "triage-linear": { dir: "triage", overlay: "linear" },
    "triage-jira": { dir: "triage", overlay: "jira" },
};
export function availableTemplates() {
    return Object.keys(TEMPLATES).sort();
}
export function resolveTemplate(name) {
    if (!/^[a-z][a-z0-9-]*$/.test(name)) {
        return {
            ok: false,
            message: "template name must match /^[a-z][a-z0-9-]*$/",
        };
    }
    const resolved = canonicalTemplateName(name);
    if (!isTemplateName(resolved)) {
        return {
            ok: false,
            message: `unknown template "${name}" (available: ${availableTemplates().join(", ")})`,
        };
    }
    const entry = TEMPLATES[resolved];
    const dir = resolvePackagePath("templates", entry.dir);
    return {
        ok: true,
        name: resolved,
        dir,
        overlayDir: entry.overlay === undefined ? undefined : join(dir, "overlays", entry.overlay),
    };
}
function resolvePackagePath(...segments) {
    if (runfiles.workspace !== undefined) {
        return runfiles.resolveWorkspaceRelative(["packages", "agent-serve", ...segments].join("/"));
    }
    return join(packageRootDir(), ...segments);
}
/**
 * Re-init must keep the mode the project was scaffolded with: template
 * scaffolds stamp `cursorAgentTemplate` into package.json, and a mismatch
 * here would silently mix default-scaffold files into a template project
 * (or the reverse).
 */
export function checkInitTarget(rootDir, template) {
    const pkgPath = join(rootDir, "package.json");
    if (!existsSync(pkgPath)) {
        return { ok: true };
    }
    const marker = readCursorAgentTemplate(rootDir);
    if (marker === template) {
        return { ok: true };
    }
    if (marker !== undefined &&
        template !== undefined &&
        canonicalTemplateName(marker) === canonicalTemplateName(template)) {
        return { ok: true };
    }
    if (template === undefined) {
        return {
            ok: false,
            message: `${rootDir} was scaffolded from the "${marker}" template; re-run with --template ${marker}`,
        };
    }
    if (marker === undefined) {
        return {
            ok: false,
            message: `${rootDir} already has a package.json without template provenance; re-run init without --template, or scaffold into a fresh directory`,
        };
    }
    return {
        ok: false,
        message: `${rootDir} was scaffolded from the "${marker}" template, not "${template}"`,
    };
}
export async function initProject(options) {
    const rootDir = resolve(options.dir);
    const projectName = basename(rootDir);
    const name = options.name ?? projectName;
    const model = formatModelLiteral(options.model ?? DEFAULT_MODEL);
    const projectRoot = resolveProjectRoot(rootDir);
    const files = [];
    const write = async (rel, contents) => {
        if (options.dryRun === true) {
            files.push({ path: rel, action: existsSync(join(rootDir, rel)) ? "exist" : "create" });
            return;
        }
        files.push({ path: rel, action: await writeNewFile(rootDir, { path: rel, contents }) });
    };
    if (options.templateDir !== undefined) {
        const templateDir = options.templateDir;
        const overlayDir = options.overlayDir;
        const overlayPaths = overlayDir ? await listTemplateFiles(overlayDir) : [];
        const overlaySet = new Set(overlayPaths);
        const corePaths = (await listTemplateFiles(templateDir)).filter((rel) => !overlaySet.has(rel));
        const templateName = options.templateName ?? basename(templateDir);
        const initSpec = options.initSpec ?? (await loadTemplateInitSpec(templateDir));
        const answers = options.answers ?? {};
        for (const rel of corePaths) {
            await writeTemplateFile({
                write,
                sourceDir: templateDir,
                rel,
                destinationRel: remapCanonicalProjectPath(rel, projectRoot),
                projectRoot,
                projectName,
                templateName,
                initSpec,
                answers,
            });
        }
        if (overlayDir !== undefined) {
            for (const rel of overlayPaths) {
                await writeTemplateFile({
                    write,
                    sourceDir: overlayDir,
                    rel,
                    destinationRel: remapCanonicalProjectPath(rel, projectRoot),
                    projectRoot,
                    projectName,
                    templateName,
                    initSpec,
                    answers,
                });
            }
        }
    }
    else {
        await writeDefaultScaffold(write, name, model, projectRoot);
    }
    await write("AGENTS.md", agentsMd(name, projectRoot));
    await write(".gitignore", GITIGNORE);
    return {
        rootDir,
        files,
        created: files.filter((entry) => entry.action === "create").map((entry) => entry.path),
        skipped: files.filter((entry) => entry.action === "exist").map((entry) => entry.path),
    };
}
async function listTemplateFiles(root) {
    const entries = await readdir(root, {
        recursive: true,
        withFileTypes: true,
    });
    return entries
        .filter((entry) => entry.isFile())
        .map((entry) => posixRel(relative(root, join(entry.parentPath, entry.name))))
        .filter((rel) => !isTemplateMetaPath(rel))
        .sort();
}
async function writeTemplateFile(input) {
    const source = join(input.sourceDir, input.rel);
    if (input.rel === "package.json") {
        const packageJson = JSON.parse(await readFile(source, "utf8"));
        packageJson.name = input.projectName;
        packageJson.dependencies[PACKAGE_NAME] = `^${packageVersion()}`;
        packageJson.cursorAgentTemplate = input.templateName;
        await input.write(input.destinationRel, `${JSON.stringify(packageJson, null, 2)}\n`);
        return;
    }
    if (input.initSpec !== undefined && templateFileHasReplacements(input.initSpec, input.rel)) {
        const contents = applyInitReplacements(await readFile(source, "utf8"), input.rel, input.initSpec, input.answers);
        await input.write(input.destinationRel, remapCanonicalProjectContents(contents, input.projectRoot));
        return;
    }
    const contents = await readFile(source, "utf8");
    await input.write(input.destinationRel, remapCanonicalProjectContents(contents, input.projectRoot));
}
export function isEexist(error) {
    return hasErrorCode(error, "EEXIST");
}
/** Writes a file unless one is already there; the action says which. */
export async function writeNewFile(rootDir, file) {
    const abs = join(rootDir, file.path);
    await mkdir(dirname(abs), { recursive: true });
    try {
        await writeFile(abs, file.contents, { flag: "wx" });
        return "create";
    }
    catch (error) {
        if (isEexist(error)) {
            return "exist";
        }
        throw error;
    }
}
function hasErrorCode(error, code) {
    return error !== null && typeof error === "object" && "code" in error && error.code === code;
}
/**
 * Install the scaffold's npm dependencies so `dev` / `run` can resolve
 * `@grok/agent-sdk` immediately after `init`.
 */
export async function installScaffoldDependencies(rootDir, options = {}) {
    const stdio = options.stdio ?? "inherit";
    const command = process.platform === "win32" ? "npm.cmd" : "npm";
    const args = ["install", "--no-fund", "--no-audit"];
    const runner = options.runner ?? defaultNpmInstallRunner;
    const result = await runner({ command, args, cwd: rootDir, stdio });
    return {
        ok: result.exitCode === 0,
        exitCode: result.exitCode,
        stderr: result.stderr,
    };
}
/** Older names of this package. Their global installs own the same bins. */
const OLDER_PACKAGE_NAMES = [PREVIOUS_PACKAGE_NAME, FORMER_PACKAGE_NAME];
/**
 * Put the CLI on the user PATH by installing the already-downloaded project
 * copy into the npm global prefix. `npx @grok/agent-sdk init` only runs the
 * package; this is the install that makes bare `agent-sdk` and `bdk`
 * work afterward.
 */
export async function linkCliOntoPath(rootDir, options = {}) {
    const packageDir = join(rootDir, "node_modules", PACKAGE_NAME);
    if (!existsSync(packageDir)) {
        return {
            ok: false,
            exitCode: 1,
            stderr: `missing ${PACKAGE_NAME} under ${packageDir} (run npm install first)`,
            replaced: [],
        };
    }
    const stdio = options.stdio ?? "inherit";
    const command = process.platform === "win32" ? "npm.cmd" : "npm";
    const runner = options.runner ?? defaultNpmInstallRunner;
    // A global install under an older name owns the `agent-sdk` and `bdk` bins,
    // and npm refuses to overwrite them (EEXIST). Remove it first.
    const prefix = await (options.globalPrefixImpl ?? npmGlobalPrefix)();
    const replaced = prefix === undefined ? [] : globalOlderPackages(prefix);
    if (replaced.length > 0) {
        const removed = await runner({
            command,
            args: ["uninstall", "--global", ...replaced],
            cwd: rootDir,
            stdio,
        });
        if (removed.exitCode !== 0) {
            return {
                ok: false,
                exitCode: removed.exitCode,
                stderr: removed.stderr.trim() ||
                    `npm uninstall --global ${replaced.join(" ")} exited ${removed.exitCode}`,
                replaced: [],
            };
        }
    }
    const args = ["install", "--global", "--no-fund", "--no-audit", packageDir];
    const result = await runner({ command, args, cwd: rootDir, stdio });
    if (result.exitCode !== 0) {
        return {
            ok: false,
            exitCode: result.exitCode,
            stderr: result.stderr,
            replaced,
        };
    }
    const resolvedPath = options.whichImpl
        ? await options.whichImpl(CLI_COMMAND_NAME)
        : resolveLinkedCli(CLI_COMMAND_NAME, prefix);
    return {
        ok: resolvedPath !== undefined,
        exitCode: 0,
        stderr: resolvedPath === undefined
            ? `${CLI_COMMAND_NAME} linked into the npm global prefix but is not on PATH; open a new shell or add that bin directory to PATH`
            : "",
        resolvedPath,
        replaced,
    };
}
/**
 * Older package names installed in the npm global prefix. A global install
 * from a project folder is a symlink, and the folder can be gone, so a
 * dangling link counts too.
 */
function globalOlderPackages(prefix) {
    const root = process.platform === "win32"
        ? join(prefix, "node_modules")
        : join(prefix, "lib", "node_modules");
    return OLDER_PACKAGE_NAMES.filter((name) => {
        try {
            lstatSync(join(root, name));
            return true;
        }
        catch {
            return false;
        }
    });
}
/** Prefer the npm-global bin; ignore an older `bdk` earlier on PATH. */
function resolveLinkedCli(commandName, prefix) {
    if (prefix === undefined) {
        return whichOnPath(commandName);
    }
    const binDir = process.platform === "win32" ? prefix : join(prefix, "bin");
    const exts = process.platform === "win32"
        ? (process.env.PATHEXT ?? ".EXE;.CMD;.BAT").split(";").filter(Boolean)
        : [""];
    for (const ext of exts) {
        const candidate = join(binDir, `${commandName}${ext}`);
        if (!existsSync(candidate)) {
            continue;
        }
        // Only claim PATH success when this linked bin is the first hit.
        const onPath = whichOnPath(commandName);
        return onPath === candidate ? candidate : undefined;
    }
    return undefined;
}
async function npmGlobalPrefix() {
    const command = process.platform === "win32" ? "npm.cmd" : "npm";
    return await new Promise((resolvePromise) => {
        const child = spawn(command, ["prefix", "-g"], {
            stdio: ["ignore", "pipe", "ignore"],
            env: process.env,
        });
        let out = "";
        child.stdout?.setEncoding("utf8");
        child.stdout?.on("data", (chunk) => {
            out += chunk;
        });
        child.on("error", () => resolvePromise(undefined));
        child.on("close", (code) => {
            if (code !== 0) {
                resolvePromise(undefined);
                return;
            }
            const prefix = out.trim();
            resolvePromise(prefix === "" ? undefined : prefix);
        });
    });
}
function whichOnPath(commandName) {
    const pathEnv = process.env.PATH ?? "";
    const sep = process.platform === "win32" ? ";" : ":";
    const exts = process.platform === "win32"
        ? (process.env.PATHEXT ?? ".EXE;.CMD;.BAT").split(";").filter(Boolean)
        : [""];
    for (const dir of pathEnv.split(sep)) {
        // npx and npm scripts put `node_modules/.bin` folders first. A new shell
        // does not have them, so they do not show what the user will run.
        if (dir === "" || (basename(dir) === ".bin" && basename(dirname(dir)) === "node_modules")) {
            continue;
        }
        for (const ext of exts) {
            const candidate = join(dir, `${commandName}${ext}`);
            if (existsSync(candidate)) {
                return candidate;
            }
        }
    }
    return undefined;
}
async function defaultNpmInstallRunner(args) {
    return await new Promise((resolvePromise, reject) => {
        const child = spawn(args.command, args.args, {
            cwd: args.cwd,
            stdio: args.stdio === "inherit" ? "inherit" : ["ignore", "pipe", "pipe"],
            env: process.env,
        });
        let stderr = "";
        if (args.stdio === "pipe") {
            child.stderr?.setEncoding("utf8");
            child.stderr?.on("data", (chunk) => {
                stderr += chunk;
            });
            child.stdout?.resume();
        }
        child.on("error", reject);
        child.on("close", (code) => {
            resolvePromise({ exitCode: code ?? 1, stderr });
        });
    });
}
function initPalette(color) {
    return color === undefined ? stdoutPalette() : makePalette(color);
}
/**
 * Created/skipped files plus the project path. Printed before an interactive
 * login so the scaffold is visible while the browser flow runs.
 */
export function formatInitScaffoldSummary(options) {
    const c = initPalette(options.color);
    const name = basename(options.rootDir);
    const lines = [];
    lines.push(`Initialized agent ${name}`);
    lines.push("");
    for (const file of options.files) {
        // Empty-dir placeholders stay on disk but clutter the summary.
        if (file.path.endsWith("/.gitkeep") || file.path === ".gitkeep") {
            continue;
        }
        // Thor/Rails status column is 12 chars, right-aligned.
        lines.push(c.dim(`${file.action.padStart(12)}  ${file.path}`));
    }
    lines.push("");
    lines.push(c.dim(`Project: ${options.rootDir}`));
    lines.push("");
    return `${lines.join("\n")}\n`;
}
/**
 * Numbered next steps after scaffold (and after login when init ran it).
 * Includes `cd` when init did not already run inside the project.
 */
export function formatInitNextSteps(options) {
    const c = initPalette(options.color);
    const lines = [];
    lines.push("Next steps:");
    lines.push("");
    const steps = initNextStepEntries(options);
    const width = Math.max(...steps.map((step) => step.command.length));
    for (const [index, step] of steps.entries()) {
        const command = step.note === undefined
            ? step.command
            : `${step.command.padEnd(width)}   ${c.dim(`# ${step.note}`)}`;
        lines.push(`  ${index + 1}. ${command}`);
    }
    return `${lines.join("\n")}\n`;
}
/**
 * Full human-readable scaffold summary (scaffold + next steps).
 */
export function formatInitSummary(options) {
    return formatInitScaffoldSummary(options) + formatInitNextSteps(options);
}
/**
 * `cd` into the scaffold when init did not already run inside it. Relative
 * when the target sits under the invoking directory, absolute otherwise.
 */
export function formatCdCommand(cwd, rootDir) {
    const rel = relative(cwd, rootDir);
    if (rel === "") {
        return undefined;
    }
    const path = rel.startsWith("..") ? rootDir : rel;
    const quoted = /\s/.test(path) ? JSON.stringify(path) : path;
    return `cd ${quoted}`;
}
function initNextStepEntries(options) {
    const steps = [];
    const cd = formatCdCommand(options.cwd, options.rootDir);
    if (cd !== undefined) {
        steps.push({ command: cd });
    }
    if (!options.signedIn) {
        const login = options.cliOnPath ? `${CLI_COMMAND_NAME} login` : `npx ${PACKAGE_NAME} login`;
        steps.push({
            command: login,
            note: "connect your Cursor account (powers model turns)",
        });
    }
    const dev = options.cliOnPath ? `${CLI_COMMAND_NAME} dev` : `npx ${PACKAGE_NAME} dev`;
    steps.push({
        command: dev,
        note: "start the local playground",
    });
    return steps;
}
/**
 * Next-step commands for the `--json` scaffold summary (login omitted when
 * the host already has a Cursor credential).
 */
export function initNextCommands(options) {
    return initNextStepEntries(options).map((step) => step.command);
}
/**
 * Coding-agent setup guide printed by `agent-sdk init`
 * with no target directory (does not scaffold).
 */
export function printInitGuide() {
    process.stdout.write(`${CLI_COMMAND_NAME} — coding agent setup

Scaffold a project, then open the playground:
  npx ${PACKAGE_NAME} init ./my-agent   # installs deps + links agent-sdk onto PATH
  npx ${PACKAGE_NAME} init ./my-demo --template demo              # record a PR walkthrough
  npx ${PACKAGE_NAME} init ./code-wiki --template code-wiki       # keep wiki pages current after merge
  npx ${PACKAGE_NAME} init ./agents-md --template agents-md       # keep AGENTS.md current from last week's PRs and Slack
  npx ${PACKAGE_NAME} init ./my-reviewer --template security-reviewer   # review PRs for security bugs
  npx ${PACKAGE_NAME} init ./thermo-review --template thermo-review       # review PRs for bugs and breakage
  npx ${PACKAGE_NAME} init ./thermo-quality --template thermo-quality-review # review PRs for code quality
  npx ${PACKAGE_NAME} init ./security-help --template security-help   # answer security questions in Slack
  npx ${PACKAGE_NAME} init ./my-triage --template triage-linear   # comment on Linear issues
  npx ${PACKAGE_NAME} init ./my-triage --template triage-jira     # comment on Jira issues
  npx ${PACKAGE_NAME} init ./my-owners --template agentic-owners  # review PRs via owners policies
  # TTY asks the template's questions. Scripts pass --var:
  #   --var repos=acme/widgets,acme/api
  #   --var agents="Plan Keeper, Chief of Staff"
  cd ./my-agent && ${CLI_COMMAND_NAME} dev        # or: npx ${PACKAGE_NAME} dev

Recommended loop once the project exists (from the project directory):
  1. Edit bot/ + tools under bot/tools/
  2. ${CLI_COMMAND_NAME} info --dir . --json
  3. ${CLI_COMMAND_NAME} run --dir . --message "..."
  4. ${CLI_COMMAND_NAME} eval --dir .

Evals:
  Blank init writes evals/evals.config.ts (maxConcurrency: 20) and
  evals/smoke.eval.ts (the echo tool; t.succeeded() and t.calledTool("echo")).
  Add more evals/**/*.eval.ts using defineEval from ${PACKAGE_NAME}/evals
  Case id is the path: evals/weather/nyc.eval.ts → weather/nyc
  maxConcurrency is hard-capped at 200 due to model provider request limits
  Run: ${CLI_COMMAND_NAME} eval [--json] [evalId...]
    (pass --prod to run against the hosted deployment)

The scaffold writes AGENTS.md (coding-agent loop for this project).
See AGENTS.md in the ${PACKAGE_NAME} package for the framework loop.
`);
}
